1	"use client";
2	
3	import Link from "next/link";
4	import { RotateCcw } from "lucide-react";
5	import { Kicker } from "@/components/ui-fitcheck/kicker";
6	import { WeatherStrip } from "./weather-strip";
7	import { OccasionRow, RefineButton } from "./occasion-row";
8	import { RefineSheet } from "./refine-sheet";
9	import { IndexTabs } from "./index-tabs";
10	import { FlatLay } from "./flat-lay";
11	import { WhyQuote } from "./why-quote";
12	import type { Look, UiOccasion, WeatherPayload } from "@/lib/generator/types";
13	import type { City } from "@/lib/weather/geocode";
14	
15	export type StylistStatus = "loading" | "ok" | "empty" | "error";
16	
17	/**
18	 * An empty result is almost never "add more pieces" — it's one specific gap for
19	 * one specific occasion (e.g. no shoes formal enough for Evening). Naming the gap
20	 * turns a dead end into a next step.
21	 */
22	function emptyCopy(missing: string | null | undefined, occasionLabel: string): string {
23	  switch (missing) {
24	    case "Shoes":
25	      return `No shoes formal enough for ${occasionLabel} — add dressier footwear, or try another occasion.`;
26	    case "Tops":
27	      return `No tops that suit ${occasionLabel} — add one, or try another occasion.`;
28	    case "Bottoms":
29	      return `No bottoms that suit ${occasionLabel} — add a pair, or try another occasion.`;
30	    default:
31	      return "Add a few more pieces to unlock outfits";
32	  }
33	}
34	
35	export function StylistView(props: {
36	  status: StylistStatus;
37	  weather: WeatherPayload | null;
38	  looks: Look[];
39	  selectedLook: number;
40	  occasion: UiOccasion;
41	  cities: City[];
42	  refineOpen: boolean;
43	  /** Required slot that blocked every combo, when status === "empty". */
44	  missing?: string | null;
45	  onOccasion: (o: UiOccasion) => void;
46	  onOpenRefine: () => void;
47	  onCloseRefine: () => void;
48	  onRefineApply: (r: { formality: number; lean: string[] }) => void;
49	  onCityChange: (c: City) => void;
50	  onCitySearch: (q: string) => void;
51	  onUseMyLocation?: () => void; // absent when the browser has no geolocation API
52	  locating: boolean;
53	  geoError: string | null;
54	  onSelectLook: (i: number) => void;
55	  onRetry: () => void;
56	  /** Decision 5: the ONLY way to spend an AI call on a day already answered. */
57	  onRegenerate: () => void;
58	  /** The legible "why" for the predicted default occasion (empty until seeded). */
59	  reason?: string;
60	}) {
61	  const { status, weather, looks, selectedLook, occasion } = props;
62	  const look = looks[selectedLook];
63	  const occLabel = occasion.charAt(0).toUpperCase() + occasion.slice(1);
64	
65	  return (
66	    <main className="relative flex flex-1 flex-col overflow-hidden px-[22px] pt-[46px]">
67	      {/* The legible "why" — a quiet kicker above the title that makes the smart
68	          default read as intentional. Uses the documented label step. */}
69	      {props.reason && (
70	        <p className="mb-1 text-[11px] uppercase tracking-[0.22em] text-muted-dim">{props.reason}</p>
71	      )}
72	      <div className="mb-[10px] flex items-center justify-between gap-3">
73	        <h1 className="font-serif text-[24px] text-foreground">Today&apos;s Looks</h1>
74	        <RefineButton onRefine={props.onOpenRefine} />
75	      </div>
76	
77	      {weather ? (
78	        <WeatherStrip
79	          weather={weather}
80	          cities={props.cities}
81	          onSearch={props.onCitySearch}
82	          onCityChange={props.onCityChange}
83	          onUseMyLocation={props.onUseMyLocation}
84	          locating={props.locating}
85	          geoError={props.geoError}
86	        />
87	      ) : (
88	        <div className="h-10 animate-pulse rounded bg-surface-1" />
89	      )}
90	
91	      <div className="mt-[11px]">
92	        <OccasionRow occasion={occasion} onOccasion={props.onOccasion} />
93	      </div>
94	
95	      {looks.length > 0 && (
96	        <div className="mt-[15px]">
97	          <IndexTabs names={looks.map((l) => l.name)} selected={selectedLook} onSelect={props.onSelectLook} />
98	        </div>
99	      )}
100	
101	      <div className="mt-[16px] flex flex-1 flex-col">
102	        {status === "loading" && (
103	          <div data-testid="stylist-skeleton" className="flex flex-1 flex-col gap-4">
104	            <div className="flex-1 animate-pulse rounded-[16px] bg-surface-1" style={{ minHeight: 200 }} />
105	            <div className="h-5 w-3/4 animate-pulse rounded bg-surface-1" />
106	          </div>
107	        )}
108	
109	        {status === "empty" && (
110	          <div className="flex flex-1 flex-col items-center justify-center gap-2 text-center">
111	            <p className="font-serif text-[20px] text-foreground">Nothing to style yet</p>
112	            <p data-testid="empty-copy" className="max-w-[30ch] text-sm text-muted-foreground">
113	              {emptyCopy(props.missing, occLabel)}
114	            </p>
115	          </div>
116	        )}
117	
